-- FitCheck schema (PostgreSQL). Generated by scripts/export_schema.py from core/db.py. Do not edit by hand.


CREATE TABLE candidates (
	id SERIAL NOT NULL, 
	display_name VARCHAR(120) NOT NULL, 
	email VARCHAR(255), 
	auth_provider VARCHAR(40) NOT NULL, 
	password_hash VARCHAR(255), 
	password_salt VARCHAR(64), 
	google_id VARCHAR(200), 
	avatar_url VARCHAR(600), 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (display_name)
);


CREATE TABLE onet_occupations (
	onet_code VARCHAR(20) NOT NULL, 
	title VARCHAR(300) NOT NULL, 
	description TEXT NOT NULL, 
	task_statements JSON NOT NULL, 
	essential_skills JSON NOT NULL, 
	transferable_skills JSON NOT NULL, 
	software_skills JSON NOT NULL, 
	source_version VARCHAR(20) NOT NULL, 
	PRIMARY KEY (onet_code)
);


CREATE TABLE skills (
	id SERIAL NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	category VARCHAR(60) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);


CREATE TABLE job_postings (
	id SERIAL NOT NULL, 
	candidate_id INTEGER, 
	title VARCHAR(200) NOT NULL, 
	company VARCHAR(200), 
	source VARCHAR(20) NOT NULL, 
	raw_path VARCHAR(600), 
	text TEXT NOT NULL, 
	is_synthetic BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE
);

CREATE INDEX ix_job_postings_candidate_id ON job_postings (candidate_id);


CREATE TABLE learning_modules (
	id SERIAL NOT NULL, 
	skill_id INTEGER NOT NULL, 
	topic_key VARCHAR(80) NOT NULL, 
	stage_no INTEGER NOT NULL, 
	stage_title VARCHAR(120) NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	position INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_module_skill_topic UNIQUE (skill_id, topic_key), 
	FOREIGN KEY(skill_id) REFERENCES skills (id) ON DELETE CASCADE
);

CREATE INDEX ix_learning_modules_skill_id ON learning_modules (skill_id);


CREATE TABLE resumes (
	id SERIAL NOT NULL, 
	candidate_id INTEGER NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	file_type VARCHAR(10) NOT NULL, 
	file_size_bytes INTEGER NOT NULL, 
	raw_path VARCHAR(600), 
	extraction_method VARCHAR(60) NOT NULL, 
	original_text TEXT NOT NULL, 
	reviewed_text TEXT NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE
);

CREATE INDEX ix_resumes_candidate_id ON resumes (candidate_id);


CREATE TABLE cv_versions (
	id SERIAL NOT NULL, 
	candidate_id INTEGER NOT NULL, 
	resume_id INTEGER NOT NULL, 
	version_no INTEGER NOT NULL, 
	content_json JSON NOT NULL, 
	content_text TEXT NOT NULL, 
	added_skill VARCHAR(100), 
	section_name VARCHAR(100), 
	note VARCHAR(255), 
	docx_bytes BYTEA, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_cv_resume_version UNIQUE (resume_id, version_no), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE, 
	FOREIGN KEY(resume_id) REFERENCES resumes (id) ON DELETE CASCADE
);

CREATE INDEX ix_cv_versions_candidate_id ON cv_versions (candidate_id);

CREATE INDEX ix_cv_versions_resume_id ON cv_versions (resume_id);


CREATE TABLE job_skills (
	job_id INTEGER NOT NULL, 
	skill_id INTEGER NOT NULL, 
	importance VARCHAR(10) NOT NULL, 
	PRIMARY KEY (job_id, skill_id), 
	CONSTRAINT ck_job_skills_importance CHECK (importance IN ('required','preferred')), 
	FOREIGN KEY(job_id) REFERENCES job_postings (id) ON DELETE CASCADE, 
	FOREIGN KEY(skill_id) REFERENCES skills (id) ON DELETE CASCADE
);


CREATE TABLE learning_paths (
	id SERIAL NOT NULL, 
	candidate_id INTEGER NOT NULL, 
	skill_id INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	started_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	completed_at TIMESTAMP WITHOUT TIME ZONE, 
	last_module_id INTEGER, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_path_candidate_skill UNIQUE (candidate_id, skill_id), 
	CONSTRAINT ck_path_status CHECK (status IN ('in_progress','completed')), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE, 
	FOREIGN KEY(skill_id) REFERENCES skills (id) ON DELETE CASCADE, 
	FOREIGN KEY(last_module_id) REFERENCES learning_modules (id) ON DELETE SET NULL
);

CREATE INDEX ix_learning_paths_candidate_id ON learning_paths (candidate_id);


CREATE TABLE learning_progress (
	id SERIAL NOT NULL, 
	candidate_id INTEGER NOT NULL, 
	module_id INTEGER NOT NULL, 
	completed BOOLEAN NOT NULL, 
	completed_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_progress_candidate_module UNIQUE (candidate_id, module_id), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE, 
	FOREIGN KEY(module_id) REFERENCES learning_modules (id) ON DELETE CASCADE
);

CREATE INDEX ix_learning_progress_candidate_id ON learning_progress (candidate_id);


CREATE TABLE resume_skills (
	resume_id INTEGER NOT NULL, 
	skill_id INTEGER NOT NULL, 
	PRIMARY KEY (resume_id, skill_id), 
	FOREIGN KEY(resume_id) REFERENCES resumes (id) ON DELETE CASCADE, 
	FOREIGN KEY(skill_id) REFERENCES skills (id) ON DELETE CASCADE
);


CREATE TABLE match_results (
	id SERIAL NOT NULL, 
	candidate_id INTEGER NOT NULL, 
	resume_id INTEGER NOT NULL, 
	job_id INTEGER NOT NULL, 
	cv_version_id INTEGER, 
	final_score FLOAT NOT NULL, 
	skill_score FLOAT NOT NULL, 
	text_similarity FLOAT NOT NULL, 
	skill_weight FLOAT NOT NULL, 
	text_weight FLOAT NOT NULL, 
	preferred_weight FLOAT NOT NULL, 
	details JSON NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_match_score_range CHECK (final_score >= 0 AND final_score <= 100), 
	FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE, 
	FOREIGN KEY(resume_id) REFERENCES resumes (id) ON DELETE CASCADE, 
	FOREIGN KEY(job_id) REFERENCES job_postings (id) ON DELETE CASCADE, 
	FOREIGN KEY(cv_version_id) REFERENCES cv_versions (id) ON DELETE SET NULL
);

CREATE INDEX ix_match_results_candidate_id ON match_results (candidate_id);

CREATE INDEX ix_match_results_job_id ON match_results (job_id);

CREATE INDEX ix_match_results_resume_id ON match_results (resume_id);

